(function () {
    'use strict';

    // 错误输出
    function logError(error) {
        try {
            if (typeof console === 'undefined') return;
            if ('error' in console) {
                console.error(error);
            } else {
                console.log(error);
            }
        } catch (e) {}
    }

    // 解析 URL，返回真实的 href
    function parseHref(html) {
        var div = document.createElement('div');
        div.innerHTML = '<a href="' + html.replace(/"/g, '&quot;') + '"></a>';
        return div.childNodes[0].getAttribute('href') || '';
    }

    // 读取两位十六进制并转成十进制
    function hexToInt(str, index) {
        var hex = str.substr(index, 2);
        return parseInt(hex, 16);
    }

    // 解码 Cloudflare 的 cfemail
    function decodeCfEmail(encoded, startIndex) {
        var result = '';
        var key = hexToInt(encoded, startIndex);

        for (var i = startIndex + 2; i < encoded.length; i += 2) {
            var code = hexToInt(encoded, i) ^ key;
            result += String.fromCharCode(code);
        }

        try {
            result = decodeURIComponent(escape(result));
        } catch (e) {
            logError(e);
        }

        return parseHref(result);
    }

    // 处理普通链接中的 /cdn-cgi/l/email-protection#
    function decodeLinks(root) {
        var links = root.querySelectorAll('a');
        for (var i = 0; i < links.length; i++) {
            try {
                var link = links[i];
                var prefixIndex = link.href.indexOf(PROTECTION_PREFIX);
                if (prefixIndex > -1) {
                    link.href = 'mailto:' + decodeCfEmail(link.href, prefixIndex + PROTECTION_PREFIX.length);
                }
            } catch (e) {
                logError(e);
            }
        }
    }

    // 处理 .__cf_email__ 元素
    function decodeEmailElements(root) {
        var elements = root.querySelectorAll(EMAIL_SELECTOR);
        for (var i = 0; i < elements.length; i++) {
            try {
                var element = elements[i];
                var parent = element.parentNode;
                var encoded = element.getAttribute(CFEMAIL_ATTR);
                if (encoded) {
                    var email = decodeCfEmail(encoded, 0);
                    var textNode = document.createTextNode(email);
                    parent.replaceChild(textNode, element);
                }
            } catch (e) {
                logError(e);
            }
        }
    }

    // 递归处理 template 内容
    function decodeTemplates(root) {
        var templates = root.querySelectorAll('template');
        for (var i = 0; i < templates.length; i++) {
            try {
                processNode(templates[i].content);
            } catch (e) {
                logError(e);
            }
        }
    }

    // 统一处理入口
    function processNode(root) {
        try {
            decodeLinks(root);
            decodeEmailElements(root);
            decodeTemplates(root);
        } catch (e) {
            logError(e);
        }
    }

    var PROTECTION_PREFIX = '/cdn-cgi/l/email-protection#';
    var EMAIL_SELECTOR = '.__cf_email__';
    var CFEMAIL_ATTR = 'data-cfemail';

    // 开始处理整个文档
    processNode(document);

    // 删除自身脚本标签
    (function removeSelf() {
        var script = document.currentScript || document.scripts[document.scripts.length - 1];
        script.parentNode.removeChild(script);
    })();
})();
